function halftoneProcess(data,w,h,opts){
  opts=opts||{};
  var S=opts.spacing!=null?opts.spacing:8;
  if(S<2)S=2;
  var gw=Math.ceil(w/S), gh=Math.ceil(h/S);
  var cellLum=new Float32Array(gw*gh);
  for(var cy=0;cy<gh;cy++) for(var cx=0;cx<gw;cx++){
    var x0=cx*S, y0=cy*S, x1=Math.min(w,x0+S), y1=Math.min(h,y0+S);
    var sum=0, n=0;
    for(var yy=y0;yy<y1;yy++) for(var xx=x0;xx<x1;xx++){
      var i=(yy*w+xx)*4; sum+=0.299*data[i]+0.587*data[i+1]+0.114*data[i+2]; n++;
    }
    cellLum[cy*gw+cx]= n>0? sum/n : 255;
  }
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var cx=Math.floor(x/S), cy=Math.floor(y/S);
    if(cx>=gw)cx=gw-1; if(cy>=gh)cy=gh-1;
    var lum=cellLum[cy*gw+cx];
    var dotR=(S/2)*Math.sqrt(Math.max(0,1-lum/255));
    var ccx=cx*S+S/2, ccy=cy*S+S/2;
    var ddx=x-ccx, ddy=y-ccy, d=Math.sqrt(ddx*ddx+ddy*ddy);
    var i=(y*w+x)*4;
    if(d<=dotR){ out[i]=0;out[i+1]=0;out[i+2]=0;out[i+3]=255; }
    else { out[i]=255;out[i+1]=255;out[i+2]=255;out[i+3]=255; }
  }
  return out;
}

var EXPORTS={halftoneProcess:halftoneProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HalftoneForgePure = EXPORTS; }
